 IF EXISTS(SELECT 1 FROM grammar.content_catalog_topics WHERE version='core-2026-09-v4' AND slug='imperatives' AND (catalog_hash<>'87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d' OR payload_md5<>'2a2d3cc12f78484798d4de2e1a619cef')) THEN RAISE EXCEPTION 'Catalog payload conflict: use a new version'; END IF;
