 IF NOT EXISTS(SELECT 1 FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='imperatives' AND catalog_hash='e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4' AND payload_md5='58d3b3edd785cea176d7b253b9dc5a61' AND md5((payload->'quizItems')::text)='a7e845e6598ab9d66f911fa442a79600') THEN RAISE EXCEPTION 'Base archive or retained questions differ'; END IF;
