INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','imperatives','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"imperatives","title":"Commands, requests and suggestions","level":"A1","order":12,"summary":"Give instructions with a base verb, make them negative, and suggest actions together.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["The unspoken subject","Negative instructions","Suggestions with let’s","Polite requests"],"rules":[{"title":"The unspoken subject","explanation":"An imperative often begins with the **base verb**. Its subject you is usually understood. This lets instructions be short without being incomplete sentences. Tone and context determine whether an imperative is helpful, firm or rude.","pattern":"**Open** the window. / **Please wait** here.","commonMistakes":["Do not add -s to an imperative, even when one person receives the instruction."],"examples":["Give a direct instruction: “**Prepare** the visitor guide, please.”","Give a direct instruction: “**Restore** the old portrait, please.”"],"skill":"form"},{"title":"Negative instructions","explanation":"Use **do not / don’t + base verb** for a prohibition or negative instruction. This also applies to be in a command: Don’t be late. Ordinary statements with be have a different negative pattern.","pattern":"**Don’t touch** the switch. / **Do not be** late.","commonMistakes":["Not touch the switch is not the usual full imperative form."],"examples":["Give a negative instruction: “Do not **prepare** the visitor guide yet.”","Give a negative instruction: “Do not **restore** the old portrait yet.”"],"skill":"meaning"},{"title":"Suggestions with let’s","explanation":"Use **let’s + base verb** to propose an action involving the speaker and other people. Let’s is a contraction of let us in this use. The negative is usually let’s not + base verb.","pattern":"**Let’s take** a break. / **Let’s not hurry**.","commonMistakes":["Lets without an apostrophe is a different verb form: she lets us leave."],"examples":["Suggest doing the task together: “Let’s **prepare** the visitor guide now.”","Suggest doing the task together: “Let’s **restore** the old portrait now.”"],"skill":"contrast"},{"title":"Polite requests","explanation":"Please can soften an instruction. Modal questions with could or would often make a request less direct. After could you or would you, retain the base verb. Please does not make every command appropriate; relationship and situation matter.","pattern":"**Could you close** the door, please?","commonMistakes":["Would you mind takes an -ing form: Would you mind closing the door? It is a different pattern."],"examples":["Complete the polite request: “Could you **prepare** the visitor guide, please?”","Complete the polite request: “Could you **restore** the old portrait, please?”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-verbs-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Give instructions with a base verb, make them negative, and suggest actions together.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"The unspoken subject","explanation":"An imperative often begins with the **base verb**. Its subject you is usually understood. This lets instructions be short without being incomplete sentences. Tone and context determine whether an imperative is helpful, firm or rude.","pattern":"**Open** the window. / **Please wait** here.","commonMistakes":["Do not add -s to an imperative, even when one person receives the instruction."],"examples":["Give a direct instruction: “**Prepare** the visitor guide, please.”","Give a direct instruction: “**Restore** the old portrait, please.”"],"skill":"form","id":"imperatives-foundation-1","domain":"sentence-types","referenceIds":["bc-verbs-reference"],"readingVersion":"core-2026-09-v3"},{"title":"Negative instructions","explanation":"Use **do not / don’t + base verb** for a prohibition or negative instruction. This also applies to be in a command: Don’t be late. Ordinary statements with be have a different negative pattern.","pattern":"**Don’t touch** the switch. / **Do not be** late.","commonMistakes":["Not touch the switch is not the usual full imperative form."],"examples":["Give a negative instruction: “Do not **prepare** the visitor guide yet.”","Give a negative instruction: “Do not **restore** the old portrait yet.”"],"skill":"meaning","id":"imperatives-foundation-2","domain":"sentence-types","referenceIds":["bc-verbs-reference"],"readingVersion":"core-2026-09-v3"},{"title":"Suggestions with let’s","explanation":"Use **let’s + base verb** to propose an action involving the speaker and other people. Let’s is a contraction of let us in this use. The negative is usually let’s not + base verb.","pattern":"**Let’s take** a break. / **Let’s not hurry**.","commonMistakes":["Lets without an apostrophe is a different verb form: she lets us leave."],"examples":["Suggest doing the task together: “Let’s **prepare** the visitor guide now.”","Suggest doing the task together: “Let’s **restore** the old portrait now.”"],"skill":"contrast","id":"imperatives-foundation-3","domain":"sentence-types","referenceIds":["bc-verbs-reference"],"readingVersion":"core-2026-09-v3"},{"title":"Polite requests","explanation":"Please can soften an instruction. Modal questions with could or would often make a request less direct. After could you or would you, retain the base verb. Please does not make every command appropriate; relationship and situation matter.","pattern":"**Could you close** the door, please?","commonMistakes":["Would you mind takes an -ing form: Would you mind closing the door? It is a different pattern."],"examples":["Complete the polite request: “Could you **prepare** the visitor guide, please?”","Complete the polite request: “Could you **restore** the old portrait, please?”"],"skill":"application","id":"imperatives-foundation-4","domain":"sentence-types","referenceIds":["bc-verbs-reference"],"readingVersion":"core-2026-09-v3"},{"domain":"sentence-types","id":"exclamative-clauses","title":"Exclamations with what and how","explanation":"Exclamatives often begin with what or how and express a strong evaluation. What introduces a noun phrase; how introduces an adjective or adverb phrase. Their order differs from ordinary questions. An exclamation mark can also turn many other sentence forms into emphatic writing, so punctuation alone does not identify an exclamative construction.","pattern":"**What a** lovely day! / **How** quickly she ran!","examples":["**What useful advice** that was!","**How patient you are**!"],"commonMistakes":["Use a/an with a singular count noun after what; omit it with plural or uncountable nouns: What beautiful flowers! What luck!"],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"sentence-types","id":"imperative-subjects-and-let","title":"Imperatives with subjects, do and let","explanation":"Although the subject you is often omitted, an imperative can have an explicit subject for contrast or allocation: You wait here; somebody call a doctor. Do can emphasise an invitation or instruction. Let can introduce permission or a third-person proposal. Distinguish let them leave from the inclusive suggestion let’s leave.","pattern":"**Do sit down. / Nobody move.**","examples":["**You take the front**, and I’ll take the back.","**Let the others finish** before we begin."],"commonMistakes":["Please and do affect tone but do not make every imperative polite in every relationship. Let’s and lets remain different forms."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["**Open** the window. / **Please wait** here.","**Don’t touch** the switch. / **Do not be** late.","**Let’s take** a break. / **Let’s not hurry**.","**Could you close** the door, please?"],"readingVersion":"core-2026-09-v4"},"stage":"1 · Sentence foundations","prerequisites":["question-forms"],"readingReferenceIds":["bc-verbs-reference","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='imperatives'
